using System; using System.Collections.Generic; using System.IO; using System.Text; using System.Security.Cryptography;
namespace CommunityPoke.UnityGit {
 public sealed class GitIndexEntry {public string Path{get;set;} public string Hash{get;set;} public uint Mode{get;set;} }
 public sealed class GitIndex { public List<GitIndexEntry> Entries{get;}=new List<GitIndexEntry>();
 public static GitIndex Read(string path){var idx=new GitIndex();if(!File.Exists(path))return idx;var b=File.ReadAllBytes(path);if(b.Length<32||Encoding.ASCII.GetString(b,0,4)!="DIRC")throw new InvalidDataException("Invalid index signature");if(BitConverter.ToUInt32(new[]{b[7],b[6],b[5],b[4]},0)!=2)throw new NotSupportedException("Only index version 2 is supported");int n=(b[8]<<24)|(b[9]<<16)|(b[10]<<8)|b[11],p=12;for(int i=0;i<n;i++){int start=p;if(p+62>b.Length-20)throw new InvalidDataException("Truncated index");uint mode=(uint)((b[p+24]<<24)|(b[p+25]<<16)|(b[p+26]<<8)|b[p+27]);p+=40;var hash=new byte[20];Buffer.BlockCopy(b,p,hash,0,20);p+=20;p+=2;int end=Array.IndexOf(b,(byte)0,p);if(end<0)throw new InvalidDataException("Missing index path");var name=Encoding.UTF8.GetString(b,p,end-p);p=end+1;while((p-start)%8!=0)p++;idx.Entries.Add(new GitIndexEntry{Path=name,Hash=BitConverter.ToString(hash).Replace("-","").ToLowerInvariant(),Mode=mode});}return idx; }
 public void Write(string path){using(var m=new MemoryStream()){var w=new BinaryWriter(m);w.Write(Encoding.ASCII.GetBytes("DIRC"));Write32(w,2);Write32(w,(uint)Entries.Count);foreach(var e in Entries){long st=m.Position;for(int i=0;i<10;i++)Write32(w,0);Write32(w,e.Mode);Write32(w,0);Write32(w,0);Write32(w,0);Write32(w,0);Write32(w,0);var hash=Convert.FromHexString(e.Hash);w.Write(hash);w.Write((ushort)0);w.Write(Encoding.UTF8.GetBytes(e.Path));w.Write((byte)0);while((m.Position-st)%8!=0)w.Write((byte)0);}w.Flush();var content=m.ToArray();using(var sha=SHA1.Create())w.Write(sha.ComputeHash(content));File.WriteAllBytes(path,m.ToArray());}}
 static void Write32(BinaryWriter w,uint x){w.Write((byte)(x>>24));w.Write((byte)(x>>16));w.Write((byte)(x>>8));w.Write((byte)x);} }
}